// that each smaller layout is a resource-matching subset of the larger ones (one
// printed board; a smaller game covers the hexes it does not use — ruling #97).
//
// Coordinate convention (§13.2): columns c increase left to right; doubled rows
// r increase top to bottom; (c,r) neighbors are (c,r±2), (c±1,r±1). A tile
// exists only if listed; no omitted coordinate is playable. `start: n` marks a
// printed numbered starting location (@1…@6).

import type { ResourceType } from './catalogs.js';

export interface MapTile {
  c: number;
  r: number;
  resource: ResourceType;
  /** Printed starting-location number (@n), if this tile is one. */
  start?: number;
}

export type LayoutId = 'two' | 'threeFour' | 'fiveSix';

