/** §4.1: the layout is chosen by player count. */
export function layoutForPlayerCount(count: number): LayoutId {
  if (count === 2) return 'two';
  if (count <= 4) return 'threeFour';
  return 'fiveSix';
}

export function tilesForLayout(id: LayoutId): MapTile[] {
  switch (id) {
    case 'two': return TWO_PLAYER_TILES;
    case 'threeFour': return THREE_FOUR_PLAYER_TILES;
    case 'fiveSix': return FIVE_SIX_PLAYER_TILES;
  }
}

/** Coordinate key used everywhere a coordinate indexes a record ("c,r"). */
export function coordKey(c: number, r: number): string {
  return `${c},${r}`;
}

// ---------------------------------------------------------------------------
// Human-facing tile labels (design doc "Hex naming for Neither Guts nor Gears",
// 2026-09-21): the engine's IDs stay the (c, r) doubled-row pairs; players see
// and say a short label like C2 / E4 / G7. The label is DERIVED here — never
// stored. Column letter: c − 4 maps A…H with c = −4 → A (chr(65 + c + 4)).
// Row number halves the doubled row (odd columns index from half r).
// ---------------------------------------------------------------------------

export function tileLabel(c: number, r: number): string {
  if ((c % 2 === 0) !== (r % 2 === 0)) throw new Error(`parity violation at (${c},${r})`);
  const letter = String.fromCharCode(65 + c + 4);
  const n = c % 2 === 0 ? r / 2 + 1 : (r + 1) / 2;
  return `${letter}${n}`;
}

/** Parse a printed label ("E4", "e4", "E 4") back to the engine's pair. */
export function tileCoord(label: string): { c: number; r: number } {
  const m = label.trim().toUpperCase().match(/^([A-I])\s*(\d+)$/);
  if (!m) throw new Error(`"${label}" is not a tile label (form: C2, E4, G7)`);
  const c = m[1]!.charCodeAt(0) - 65 - 4;
  const n = parseInt(m[2]!, 10);
  const r = c % 2 === 0 ? 2 * (n - 1) : 2 * n - 1;
  if ((c % 2 === 0) !== (r % 2 === 0)) throw new Error(`label parity mismatch on "${label}"`);
  return { c, r };
}

/** The four unique scarce tiles also carry printed place names (§13.2 note). */
export const TILE_PROPER_NAMES: Readonly<Record<string, string>> = {
  E4: 'North Oil',
  E5: 'South Oil',
  D4: 'West Cauldron',
  F4: 'East Cauldron',
};

/** Display name for a tile: label (+ proper name where printed). */
export function tileDisplay(c: number, r: number): string {
  const label = tileLabel(c, r);
  const proper = TILE_PROPER_NAMES[label];
  return proper ? `${label} (${proper})` : label;
}

/** §13.2 doubled-row neighbor offsets. */
export const NEIGHBOR_OFFSETS: ReadonlyArray<readonly [number, number]> = [
  [0, -2], [0, 2], [-1, -1], [-1, 1], [1, -1], [1, 1],
];

/** Coordinate lookup per tile set. A layout's tile list is never grown or
 *  shrunk after creation, so one lookup per list is safe to keep; it spares
 *  rebuilding the map on every neighbour query (the payment search asks
 *  thousands of them per decision). */
const TILE_INDEX = new WeakMap<MapTile[], Map<string, MapTile>>();

/** The neighbors of (c,r) that exist in the given layout's tile set. */
export function neighborsOf(tiles: MapTile[], c: number, r: number): MapTile[] {
  let byKey = TILE_INDEX.get(tiles);
  if (!byKey || byKey.size !== tiles.length) {
    byKey = new Map(tiles.map((t) => [coordKey(t.c, t.r), t]));
    TILE_INDEX.set(tiles, byKey);
  }
  const out: MapTile[] = [];
  for (const [dc, dr] of NEIGHBOR_OFFSETS) {
    const t = byKey.get(coordKey(c + dc, r + dr));
    if (t) out.push(t);
  }
  return out;
}
